7	public interface IQuarantinePublisher { Task PublishAsync(QuarantineMessage message, CancellationToken token); }
8	public sealed class QuarantineException(Exception failure) : Exception("Quarantine acceptance is unresolved; do not acknowledge the original delivery.", failure);
9	public sealed class RabbitMqQuarantinePublisher(IConnectionFactory factory, IOptions<ConsumerOptions> options, TimeProvider clock, ILogger<RabbitMqQuarantinePublisher> logger) : IQuarantinePublisher
10	{
11	    public async Task PublishAsync(QuarantineMessage message, CancellationToken token)
12	    {
13	        var o = options.Value;
14	        using var budget = new CancellationTokenSource(TimeSpan.FromSeconds(o.QuarantineBudgetSeconds), clock);
15	        using var linked = CancellationTokenSource.CreateLinkedTokenSource(token, budget.Token);
16	        IConnection? connection = null; IChannel? channel = null;
17	        try
18	        {
19	            connection = await factory.CreateConnectionAsync(linked.Token).WaitAsync(linked.Token);
20	            channel = await connection.CreateChannelAsync(new CreateChannelOptions(true, true), linked.Token).WaitAsync(linked.Token);
21	            await channel.ExchangeDeclareAsync(o.QuarantineExchange, ExchangeType.Direct, true, false, cancellationToken: linked.Token).WaitAsync(linked.Token);
22	            await channel.QueueDeclareAsync(o.QuarantineQueue, true, false, false, cancellationToken: linked.Token).WaitAsync(linked.Token);
23	            await channel.QueueBindAsync(o.QuarantineQueue, o.QuarantineExchange, o.QuarantineRoutingKey, cancellationToken: linked.Token).WaitAsync(linked.Token);
24	            var properties = new BasicProperties
25	            {
26	                Persistent = true,
27	                ContentType = "application/octet-stream",
28	                Type = "JobSearchQuarantined",
29	                MessageId = message.MessageId,
30	                CorrelationId = message.CorrelationId,
31	                Timestamp = new AmqpTimestamp(clock.GetUtcNow().ToUnixTimeSeconds()),
32	                Headers = new Dictionary<string, object?> { ["failureCode"] = message.Code, ["sourceContentType"] = message.ContentType }
33	            };
34	            // Own the buffer if a timed-out dependency retains it beyond the consumer callback.
35	            await channel.BasicPublishAsync(o.QuarantineExchange, o.QuarantineRoutingKey, true, properties, message.Body.ToArray(), linked.Token).AsTask().WaitAsync(linked.Token);
36	            SearchMetrics.Quarantine("confirmed");
37	        }
38	        catch (Exception ex)
39	        {
40	            SearchMetrics.Quarantine("failed");
41	            throw new QuarantineException(ex);
42	        }
43	        finally
44	        {
45	            if (channel is not null) await CleanupAsync(channel, linked.Token);
46	            if (connection is not null) await CleanupAsync(connection, linked.Token);
47	        }
48	    }
49	    private async Task CleanupAsync(IAsyncDisposable resource, CancellationToken token)
50	    {
51	        try { await resource.DisposeAsync().AsTask().WaitAsync(TimeSpan.FromSeconds(1), clock, token); }
52	        catch (Exception ex) { logger.LogWarning(new EventId(4202, "QuarantineDisposeFailed"), "Quarantine resource cleanup failed; failure {Failure}", ex.GetType().Name); }
53	    }
54	}
