7	public sealed class RabbitMqConsumerSession(IConnectionFactory factory, IOptions<ConsumerOptions> options, IServiceScopeFactory scopes, ILogger<RabbitMqConsumerSession> logger, IQuarantinePublisher quarantine, IngestionState state, TimeProvider clock) : IConsumerSession
8	{
9	    public async Task RunAsync(CancellationToken token)
10	    {
11	        var o = options.Value;
12	        using var lifetime = new CancellationTokenSource();
13	        var processingToken = lifetime.Token; var drain = new SessionDrain(); string? consumerTag = null; var closing = 0;
14	        var failure = new TaskCompletionSource<Exception>(TaskCreationOptions.RunContinuationsAsynchronously);
15	        IConnection? connection = null; IChannel? channel = null;
16	        var settlements = new SemaphoreSlim(1);
17	        var processing = new SemaphoreSlim(o.Concurrency);
18	        try
19	        {
20	            connection = await factory.CreateConnectionAsync(token);
21	            channel = await connection.CreateChannelAsync(new CreateChannelOptions(false, false, consumerDispatchConcurrency: (ushort)o.Concurrency), token);
22	            var owner = channel; // Never replace the channel captured by a callback/tag.
23	            channel.ChannelShutdownAsync += (_, _) => { if (Volatile.Read(ref closing) == 0) failure.TrySetResult(new IOException("Consumer channel closed.")); return Task.CompletedTask; };
24	            await channel.ExchangeDeclareAsync(o.Exchange, ExchangeType.Direct, true, false, cancellationToken: token);
25	            await channel.QueueDeclareAsync(o.Queue, true, false, false, cancellationToken: token);
26	            await channel.QueueBindAsync(o.Queue, o.Exchange, o.RoutingKey, cancellationToken: token);
27	            await channel.BasicQosAsync(0, (ushort)o.Prefetch, false, token);
28	            var consumer = new AsyncEventingBasicConsumer(channel);
29	            consumer.UnregisteredAsync += (_, _) => { if (Volatile.Read(ref closing) == 0) failure.TrySetResult(new IOException("Consumer subscription ended.")); return Task.CompletedTask; };
30	            consumer.ReceivedAsync += async (_, delivery) =>
31	            {
32	                if (!drain.TryEnter()) return;
33	                try
34	                {
35	                    await processing.WaitAsync(processingToken);
36	                    try
37	                    {
38	                        // Body is processed within callback lifetime: no borrowed memory escapes.
39	                        if (delivery.Redelivered) JobSearch.Api.Diagnostics.SearchMetrics.Redelivery();
40	                        try
41	                        {
42	                            var metadata = Metadata(delivery.BasicProperties);
43	                            await using var scope = scopes.CreateAsyncScope();
44	                            var result = await scope.ServiceProvider.GetRequiredService<ISearchEventHandler>().HandleAsync(delivery.Body, metadata, processingToken);
45	                            JobSearch.Api.Diagnostics.SearchMetrics.Projection(result);
46	                        }
47	                        catch (PermanentDeliveryException ex)
48	                        {
49	                            await quarantine.PublishAsync(new(delivery.Body, ex.Code, delivery.BasicProperties.MessageId, delivery.BasicProperties.CorrelationId, delivery.BasicProperties.ContentType), processingToken);
50	                            logger.LogWarning(new EventId(4201, "DeliveryQuarantined"), "Delivery quarantined; reason {Reason}", ex.Code);
51	                        }
52	                        await settlements.WaitAsync(processingToken);
53	                        try
54	                        {
55	                            processingToken.ThrowIfCancellationRequested();
56	                            if (!owner.IsOpen) throw new IOException("Delivery channel closed.");
57	                            await owner.BasicAckAsync(delivery.DeliveryTag, false, processingToken);
58	                        }
59	                        finally { settlements.Release(); }
60	                    }
61	                    finally { processing.Release(); }
62	                }
63	                catch (Exception ex) { failure.TrySetResult(ex); }
64	                finally { drain.Exit(); }
65	            };
66	            consumerTag = await channel.BasicConsumeAsync(o.Queue, false, consumer, token);
67	            state.Set(ConsumerState.Running);
68	            throw await failure.Task.WaitAsync(token);
69	        }
70	        finally
71	        {
72	            Interlocked.Exchange(ref closing, 1);
73	            var pending = drain.Stop();
74	            if (token.IsCancellationRequested)
75	            {
76	                state.Set(ConsumerState.Draining);
77	                using var budget = new CancellationTokenSource(TimeSpan.FromSeconds(o.DrainSeconds), clock);
78	                try
79	                {
80	                    if (channel is not null && consumerTag is not null && channel.IsOpen)
81	                        await channel.BasicCancelAsync(consumerTag, true, budget.Token).WaitAsync(budget.Token);
82	                    await pending.WaitAsync(budget.Token);
83	                }
84	                catch (Exception ex) { logger.LogWarning(new EventId(4103, "DrainIncomplete"), "Consumer drain incomplete; failure {Failure}", ex.GetType().Name); }
85	            }
86	            await lifetime.CancelAsync();
87	            if (channel is not null) await DisposeResourceAsync(channel);
88	            if (connection is not null) await DisposeResourceAsync(connection);
89	        }
90	    }
91	    private async Task DisposeResourceAsync(IAsyncDisposable resource)
92	    {
93	        try { await resource.DisposeAsync().AsTask().WaitAsync(TimeSpan.FromSeconds(3)); }
94	        catch (Exception ex) { logger.LogWarning(new EventId(4102, "ConsumerDisposeFailed"), "Consumer resource cleanup failed; failure {Failure}", ex.GetType().Name); }
95	    }
96	    public static EventMetadata Metadata(IReadOnlyBasicProperties properties)
97	    {
98	        int? version = null;
99	        if (properties.Headers is not null && properties.Headers.TryGetValue("schemaVersion", out var raw))
100	            version = raw switch
101	            {
102	                byte v => v,
103	                sbyte v => v,
104	                short v => v,
105	                ushort v => v,
106	                int v => v,
107	                long v when v is >= int.MinValue and <= int.MaxValue => (int)v,
108	                _ => throw new PermanentDeliveryException("invalid_metadata")
109	            };
110	        return new(properties.MessageId, properties.Type, version, properties.ContentType);
111	    }
112	}
