4	public interface IConsumerSession { Task RunAsync(CancellationToken token); }
5	public sealed class SearchConsumerWorker(IConsumerSession session, IOptions<ConsumerOptions> options, TimeProvider clock, ILogger<SearchConsumerWorker> logger, IngestionState state, IBackoffJitter jitter) : BackgroundService
6	{
7	    protected override Task ExecuteAsync(CancellationToken token) => RunAsync(token);
8	    public async Task RunAsync(CancellationToken token)
9	    {
10	        if (!options.Value.Enabled) { state.Set(ConsumerState.Disabled); return; }
11	        var attempt = 0;
12	        try
13	        {
14	            while (!token.IsCancellationRequested)
15	            {
16	                state.Set(ConsumerState.Connecting);
17	                var started = clock.GetTimestamp();
18	                try { await session.RunAsync(token); attempt = 0; }
19	                catch (OperationCanceledException) when (token.IsCancellationRequested) { return; }
20	                catch (Exception ex)
21	                {
22	                    if (clock.GetElapsedTime(started) >= TimeSpan.FromSeconds(30)) attempt = 0;
23	                    logger.LogWarning(new EventId(4100, "ConsumerSessionFailed"), "Consumer session ended; classification {Classification}; failure {Failure}", ConsumerFailures.Classify(ex), ex.GetType().Name);
24	                }
25	                state.Set(ConsumerState.Backoff);
26	                var delay = ConsumerFailures.Delay(attempt, options.Value, jitter.Next()); attempt = Math.Min(30, attempt + 1);
27	                try { await Task.Delay(delay, clock, token); }
28	                catch (OperationCanceledException) { return; }
29	            }
30	        }
31	        finally { state.Set(ConsumerState.Stopped); }
32	    }
33	}
