    {
        try { await resource.DisposeAsync().AsTask().WaitAsync(TimeSpan.FromSeconds(1), clock, token); }
        catch (Exception ex)
        {
            logger.LogWarning(
                new EventId(4202, "QuarantineDisposeFailed"),
                "Quarantine resource cleanup failed; failure {Failure}",
                ex.GetType().Name);
        }
    }
}

